def main():
    S = json.load(open(os.path.join(R, 'sprites', 'requests', 'audio.json'), encoding='utf-8'))
    C = {c['id']: c for c in S['cues']}
    items = {}
    for k, (note, words) in W.items():
        c = C.get(k, {})
        items[k] = {'why': ('Kris: "' + note + '"') if note else 'Kris: ＋ Remake up to 5 (keep my ★, more to choose from)', 'meaning': c.get('name', k) + ' — ' + (c.get('where') or ''),
                    'secs': c.get('secs', 1), 'words': [w + T for w in words]}
    J = {'round': 131, 'take': 'z', 'note': 'Round 131: new takes for the 42 effects Kris sent back (audio\\incoming\\<id>.z1.mp3 … ). The words follow his notes; for "＋ Remake up to 5" they are close cousins of what he ★.', 'items': items}
    json.dump(J, open(os.path.join(R, 'sprites', 'requests', 'sfx_remake.json'), 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
    open(os.path.join(R, 'lab', 'src', 'js', '79m1f-lab-sfx-remake131.js'), 'w', encoding='utf-8').write(
        '// ═══════════════════════════════════════════════════════════════════════\n// ║ 79m1f-lab-sfx-remake131.js — round 131: the words for the third remake (generated by tools/audio/sfx_remake131.py; made on the PC by\n'
        '// ║ tools/audio/audio8.ps1 as <id>.z1 …). The Sound effects tab (79m3) shows them first.\n// ═══════════════════════════════════════════════════════════════════════\n'
        '(function(){ if(typeof ZAUD==="undefined")return;\n  ZAUD.REMAKE131=' + json.dumps(J, ensure_ascii=False) + ';\n})();\n')
    print(len(items), 'effects,', sum(len(v['words']) for v in items.values()), 'takes')
if __name__ == '__main__': main()
